            'message': 'Image successfully uploaded',
            'filename': filename,
            'description': description,
            'hashtags': hashtags
        }), 200
    else:
        return jsonify({'error': 'Invalid file type'}), 400

if __name__ == '__main__':
    os.makedirs(UPLOAD_FOLDER, exist_ok=True)
    app.run(debug=True)
