from flask_socketio import SocketIO, emit, join_room
import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///messages.db'
app.config['SECRET_KEY'] = 'secret!'
db = SQLAlchemy(app)
socketio = SocketIO(app, cors_allowed_origins="*")

# Define the Message model
class Message(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(100), nullable=False)
    message = db.Column(db.String(500), nullable=False)
    timestamp = db.Column(db.DateTime, default=datetime.datetime.utcnow)

    def to_dict(self):
        return {
            'id': self.id,
            'username': self.username,
            'message': self.message,
            'timestamp': self.timestamp.isoformat()
        }

# Create the database and the database table
with app.app_context():
    db.create_all()

# Route to get message history
@app.route('/history')
def get_message_history():
    messages = Message.query.order_by(Message.timestamp).all()
    return {'messages': [msg.to_dict() for msg in messages]}

# SocketIO event to handle incoming messages
@socketio.on('message')
def handle_message(data):
    username = data.get('username')
    message = data.get('message')

    if not username or not message:
        return

    # Save message to database
    new_message = Message(username=username, message=message)
    db.session.add(new_message)
    db.session.commit()

    # Broadcast message to all clients
    emit('message', data, broadcast=True)

# SocketIO event to join a room (optional) - useful if you have multiple rooms
@socketio.on('join')
def on_join(data):
    username = data.get('username')
    room = data.get('room')
    join_room(room)
    emit('message', {'username': 'System', 'message': f'{username} has joined the room'}, room=room)

if __name__ == '__main__':
    socketio.run(app, debug=True)
